public class DateTimeZone_getOffsetFromLocal_TriageGen0Test {

    /**
     * Since DateTimeZone is abstract and has a protected constructor, 
     * we use Mockito to spy on a subclass or a mock to control the behavior 
     * of the abstract methods (getOffset, nextTransition, previousTransition).
     */

    @Test
    public void testGetOffsetFromLocal_DefaultPath_SameOffset() {
        // Scenario: offsetLocal == offsetAdjusted
        DateTimeZone zone = spy(new TestDateTimeZone("UTC"));
        long instantLocal = 1000L;

        // offsetLocal = 0
        when(zone.getOffset(instantLocal)).thenReturn(0);
        // instantAdjusted = 1000 - 0 = 1000
        // offsetAdjusted = 0
        when(zone.getOffset(1000L)).thenReturn(0);

        int result = zone.getOffsetFromLocal(instantLocal);
        assertEquals(0, result);
    }

    @Test
    public void testGetOffsetFromLocal_DST_Gap_NegativeDifference_NextTransitionDifferent() {
        // Scenario: offsetLocal != offsetAdjusted AND (offsetLocal - offsetAdjusted) < 0
        // AND nextLocal != nextAdjusted
        // Should return offsetLocal
        DateTimeZone zone = spy(new TestDateTimeZone("DST_GAP"));
        long instantLocal = 2000L;

        int offsetLocal = 100;
        int offsetAdjusted = 200; // offsetLocal - offsetAdjusted = -100 (< 0)
        long instantAdjusted = instantLocal - offsetLocal; // 2000 - 100 = 1900

        when(zone.getOffset(instantLocal)).thenReturn(offsetLocal);
        when(zone.getOffset(instantAdjusted)).thenReturn(offsetAdjusted);

        // nextLocal = nextTransition(instantAdjusted)
        long nextLocal = 3000L;
        // nextAdjusted = nextTransition(instantLocal - offsetAdjusted)
        long nextAdjusted = 4000L;

        when(zone.nextTransition(instantAdjusted)).thenReturn(nextLocal);
        when(zone.nextTransition(instantLocal - offsetAdjusted)).thenReturn(nextAdjusted);

        int result = zone.getOffsetFromLocal(instantLocal);
        assertEquals(offsetLocal, result);
    }

    @Test
    public void testGetOffsetFromLocal_DST_Gap_NegativeDifference_NextTransitionSame() {
        // Scenario: offsetLocal != offsetAdjusted AND (offsetLocal - offsetAdjusted) < 0
        // AND nextLocal == nextAdjusted
        // Should return offsetAdjusted
        DateTimeZone zone = spy(new TestDateTimeZone("DST_GAP_SAME"));
        long instantLocal = 2000L;

        int offsetLocal = 100;
        int offsetAdjusted = 200;
        long instantAdjusted = instantLocal - offsetLocal;

        when(zone.getOffset(instantLocal)).thenReturn(offsetLocal);
        when(zone.getOffset(instantAdjusted)).thenReturn(offsetAdjusted);

        long nextVal = 3000L;
        when(zone.nextTransition(instantAdjusted)).thenReturn(nextVal);
        when(zone.nextTransition(instantLocal - offsetAdjusted)).thenReturn(nextVal);

        int result = zone.getOffsetFromLocal(instantLocal);
        assertEquals(offsetAdjusted, result);
    }

    @Test
    public void testGetOffsetFromLocal_PositiveOffset_PrevTransitionConditionMet() {
        // Scenario: offsetLocal == offsetAdjusted AND offsetLocal > 0
        // AND prev < instantAdjusted
        // AND instantAdjusted - prev <= diff
        // Should return offsetPrev
        DateTimeZone zone = spy(new TestDateTimeZone("POS_OFFSET"));
        long instantLocal = 5000L;
        int offsetLocal = 3600; // offsetLocal > 0

        long instantAdjusted = instantLocal - offsetLocal; // 1400

        when(zone.getOffset(instantLocal)).thenReturn(offsetLocal);
        when(zone.getOffset(instantAdjusted)).thenReturn(offsetLocal);

        long prev = 1000L;
        when(zone.previousTransition(instantAdjusted)).thenReturn(prev);

        int offsetPrev = 7200;
        int diff = offsetPrev - offsetLocal; // 3600
        // condition: instantAdjusted - prev <= diff -> 1400 - 1000 = 400 <= 3600 (True)
        when(zone.getOffset(prev)).thenReturn(offsetPrev);

        int result = zone.getOffsetFromLocal(instantLocal);
        assertEquals(offsetPrev, result);
    }

    @Test
    public void testGetOffsetFromLocal_PositiveOffset_PrevTransitionConditionNotMet() {
        // Scenario: offsetLocal == offsetAdjusted AND offsetLocal > 0
        // AND prev < instantAdjusted
        // AND instantAdjusted - prev > diff
        // Should return offsetAdjusted
        DateTimeZone zone = spy(new TestDateTimeZone("POS_OFFSET_FAIL"));
        long instantLocal = 5000L;
        int offsetLocal = 3600;

        long instantAdjusted = instantLocal - offsetLocal;

        when(zone.getOffset(instantLocal)).thenReturn(offsetLocal);
        when(zone.getOffset(instantAdjusted)).thenReturn(offsetLocal);

        long prev = 1000L;
        when(zone.previousTransition(instantAdjusted)).thenReturn(prev);

        int offsetPrev = 3700;
        int diff = offsetPrev - offsetLocal; // 100
        // condition: 1400 - 1000 = 400 <= 100 (False)
        when(zone.getOffset(prev)).thenReturn(offsetPrev);

        int result = zone.getOffsetFromLocal(instantLocal);
        assertEquals(offsetLocal, result);
    }

    @Test
    public void testGetOffsetFromLocal_PositiveOffset_PrevTransitionNotBefore() {
        // Scenario: offsetLocal == offsetAdjusted AND offsetLocal > 0
        // AND prev >= instantAdjusted
        // Should return offsetAdjusted
        DateTimeZone zone = spy(new TestDateTimeZone("POS_OFFSET_PREV_NOT_BEFORE"));
        long instantLocal = 5000L;
        int offsetLocal = 3600;
        long instantAdjusted = instantLocal - offsetLocal;

        when(zone.getOffset(instantLocal)).thenReturn(offsetLocal);
        when(zone.getOffset(instantAdjusted)).thenReturn(offsetLocal);
        when(zone.previousTransition(instantAdjusted)).thenReturn(instantAdjusted);

        int result = zone.getOffsetFromLocal(instantLocal);
        assertEquals(offsetLocal, result);
    }

    @Test
    public void testGetOffsetFromLocal_ZeroOrNegativeOffset_NoPrevCheck() {
        // Scenario: offsetLocal == offsetAdjusted AND offsetLocal <= 0
        // Should return offsetAdjusted
        DateTimeZone zone = spy(new TestDateTimeZone("ZERO_OFFSET"));
        long instantLocal = 1000L;
        int offsetLocal = 0;

        when(zone.getOffset(instantLocal)).thenReturn(offsetLocal);
        when(zone.getOffset(instantLocal)).thenReturn(offsetLocal);

        int result = zone.getOffsetFromLocal(instantLocal);
        assertEquals(0, result);
    }

    // Helper class to allow instantiation of the abstract DateTimeZone
    private static class TestDateTimeZone extends DateTimeZone {
        private final String id;
        protected TestDateTimeZone(String id) {
            super(id);
            this.id = id;
        }
        @Override public String getID() { return id; }
        @Override public String getNameKey(long instant) { return ""; }
        @Override public String getName(long instant) { return ""; }
        @Override public int getStandardOffset(long instant) { return 0; }
        @Override public boolean isStandardOffset(long instant) { return true; }
        @Override public boolean isFixed() { return false; }
        @Override public long nextTransition(long instant) { return 0; }
        @Override public long previousTransition(long instant) { return 0; }
        @Override public int getOffset(long instant) { return 0; }
    }
}
